parts.openscad_module:
$fn = 64;

rod_d       = 8;
lm_od       = 15;
lm_length   = 24;
rod_spacing = 40;
end_wall    = 6;
side_wall   = 5;
top_wall    = 4;
mount_hole_d = 4.5;

car_l = lm_length + 2*end_wall;
car_w = rod_spacing + lm_od + 2*side_wall;
car_h = lm_od + top_wall;

module dual_rod_carriage() {
  difference() {
    cube([car_l, car_w, car_h], center = true);
    for (y = [-rod_spacing/2, rod_spacing/2])
      translate([0, y, -top_wall/2])
        rotate([0, 90, 0])
          cylinder(h = car_l + 2, d = lm_od + 0.1, center = true, $fn = 64);
    for (x = [-car_l/4, car_l/4])
      for (y = [-car_w/4, car_w/4])
        translate([x, y, car_h/2])
          cylinder(h = top_wall + 2, d = mount_hole_d, center = true, $fn = 32);
  }
}

dual_rod_carriage();
